const char* command_arg_name(std::uint32_t cmd_id, std::uint32_t arg_idx) {
    for (const auto& s : kSchemas) {
        if (s.cmd_id != cmd_id) continue;
        if (arg_idx >= s.count) return nullptr;
        return kArgNamePool[kFlatArgIndices[s.start + arg_idx]];
    }
    return nullptr;
}

